diff --git a/src/main/java/com/couchbase/client/java/error/InvalidPasswordException.java b/src/main/java/com/couchbase/client/java/error/InvalidPasswordException.java
new file mode 100644
index 0000000000000000000000000000000000000000..8b0f55184f659fd9be24432699040e94e2b1bf0f
--- /dev/null
+++ b/src/main/java/com/couchbase/client/java/error/InvalidPasswordException.java
@@ -0,0 +1,27 @@
+package com.couchbase.client.java.error;
+
+import com.couchbase.client.core.CouchbaseException;
+
+/**
+ * This exception is commonly raised when the password for a resource does not match.
+ *
+ * @author Michael Nitschinger
+ * @since 2.0
+ */
+public class InvalidPasswordException extends CouchbaseException {
+
+    public InvalidPasswordException() {
+    }
+
+    public InvalidPasswordException(String message) {
+        super(message);
+    }
+
+    public InvalidPasswordException(String message, Throwable cause) {
+        super(message, cause);
+    }
+
+    public InvalidPasswordException(Throwable cause) {
+        super(cause);
+    }
+}

