diff --git a/src/main/java/com/couchbase/client/java/MutationState.java b/src/main/java/com/couchbase/client/java/MutationState.java
index bd2349fd76ab5c730146a7f5b2e786b0ef8b94ba..77d5f9fdce156c7974a1e3726fd65ba6582b24f5 100644
--- a/src/main/java/com/couchbase/client/java/MutationState.java
+++ b/src/main/java/com/couchbase/client/java/MutationState.java
@@ -163,4 +163,59 @@ public class MutationState implements Iterable<MutationToken> {
         }
         return result;
     }
+
+    /**
+     * Create a {@link MutationState} from the serialized state.
+     *
+     * @param source the source state, serialized.
+     * @return the created {@link MutationState}.
+     */
+    public static MutationState stringImport(String source) {
+        return jsonImport(JsonObject.fromJson(source));
+    }
+
+    /**
+     * Create a {@link MutationState} from the serialized state.
+     *
+     * @param source the source state, serialized.
+     * @return the created {@link MutationState}.
+     */
+    public static MutationState jsonImport(JsonObject source) {
+        try {
+            MutationState state = new MutationState();
+            for (String bucketName : source.getNames()) {
+                JsonObject bucket = source.getObject(bucketName);
+                for (String vbid : bucket.getNames()) {
+                    JsonArray values = bucket.getArray(vbid);
+                    state.addToken(new MutationToken(
+                        Long.parseLong(vbid),
+                        Long.parseLong(values.getString(1)),
+                        values.getLong(0),
+                        bucketName
+                    ));
+                }
+            }
+            return state;
+        } catch (Exception ex) {
+            throw new IllegalStateException("Could not import MutationState from JSON.", ex);
+        }
+    }
+
+    @Override
+    public boolean equals(Object o) {
+        if (this == o) return true;
+        if (o == null || getClass() != o.getClass()) return false;
+        MutationState state = (MutationState) o;
+        return tokens.containsAll(state.tokens) && state.tokens.containsAll(tokens);
+    }
+
+    @Override
+    public int hashCode() {
+        return tokens.hashCode();
+    }
+
+    @Override
+    public String toString() {
+        return "MutationState{tokens=" + tokens + '}';
+    }
 }
